/* Pointer and keyboard hints share one lightweight tooltip; motion is optional. */
(function(){let tip;function hide(){tip?.classList.remove('visible')}function show(node,event){if(!tip){tip=document.createElement('div');tip.className='chart-tooltip';tip.setAttribute('role','status');tip.setAttribute('aria-live','polite');document.body.appendChild(tip)}tip.textContent=node.dataset.chartHint;const r=node.getBoundingClientRect(),cx=event?.clientX??r.x+r.width/2,cy=event?.clientY??r.y;tip.style.left=Math.max(10,Math.min(innerWidth-240,cx-100))+'px';tip.style.top=Math.max(10,cy-60)+'px';tip.classList.add('visible')}
document.addEventListener('pointerover',event=>{const node=event.target.closest('[data-chart-hint]');if(node)show(node,event)});document.addEventListener('pointermove',event=>{const node=event.target.closest('[data-chart-hint]');if(node){show(node,event);return}const card=event.target.closest('.stat-card,.product-card,.category');if(!card||!window.matchMedia('(hover:hover) and (prefers-reduced-motion:no-preference)').matches)return;const r=card.getBoundingClientRect(),rx=(event.clientY-r.top-r.height/2)/r.height*-5,ry=(event.clientX-r.left-r.width/2)/r.width*5;card.style.transform=`perspective(1000px) translateY(-3px) rotateX(${rx}deg) rotateY(${ry}deg)`});document.addEventListener('pointerout',event=>{const node=event.target.closest('[data-chart-hint]');if(node&&!node.contains(event.relatedTarget))hide();const card=event.target.closest('.stat-card,.product-card,.category');if(card&&!card.contains(event.relatedTarget))card.style.transform=''});document.addEventListener('focusin',event=>{const node=event.target.closest('[data-chart-hint]');if(node)show(node)});document.addEventListener('focusout',hide);window.addEventListener('scroll',hide,true);window.addEventListener('hashchange',hide);document.addEventListener('keydown',event=>{if(event.key==='Escape')hide();const button=event.target.closest('[role=button][data-act]');if(button&&(event.key==='Enter'||event.key===' ')){event.preventDefault();button.dispatchEvent(new MouseEvent('click',{bubbles:true}))}});
})();
